"""Render and parse the frozen job environment file.

``run_singularity.sh`` sources ``docker/cluster/job_env.resolved.sh`` when
present and then skips its legacy ``.env.cluster`` re-source entirely, so this
file is the single config channel between ``plan`` and the compute node.
"""

from __future__ import annotations

import re
import shlex
from pathlib import Path

from imitation_experiments.paper.common import PipelineError

_KEY_RE = re.compile(r"^[A-Za-z_][A-Za-z0-9_]*$")


def render_job_env(env: dict[str, str], *, plan_sha: str, stage: str) -> str:
    lines = [
        "# Generated by `python -m imitation_experiments.pipeline.cluster plan`.",
        f"# plan_sha={plan_sha} stage={stage}",
        "# Do not edit: run_singularity.sh sources ONLY this file when present.",
    ]
    for key in sorted(env):
        if not _KEY_RE.match(key):
            raise PipelineError(f"invalid environment variable name: '{key}'")
        lines.append(f"export {key}={shlex.quote(str(env[key]))}")
    return "\n".join(lines) + "\n"


def parse_env_file(path: Path) -> dict[str, str]:
    """Parse a legacy ``KEY=VALUE`` env file (used by parity tests only)."""
    if not path.is_file():
        raise PipelineError(f"env file not found: {path}")
    parsed: dict[str, str] = {}
    for raw_line in path.read_text().splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue
        key, _, value = line.partition("=")
        key = key.strip()
        if _KEY_RE.match(key):
            parsed[key] = value.strip()
    return parsed
